function startLogin(){document.body.innerHTML='<div class="login"><section class="login-left"><div class="brand"><div class="brand-mark">TB</div><div><strong>DIENSTBUCH</strong><small>Elektronisches Wachbuch</small></div></div><div><span class="eyebrow" style="color:#d8f17b">WACHE TOR B · CHEMNITZ</span><h1>Aufmerksam.<br>Verlässlich.<br>Dokumentiert.</h1><p>Das digitale Schichtbuch für einen sicheren und nachvollziehbaren Wachdienst.</p></div><small style="color:#829087">INTERNE ANWENDUNG · DEMO</small></section><section class="login-right"><form class="login-box" id="loginForm"><div class="brand-mark" style="margin-bottom:25px">TB</div><h2>Willkommen zurück</h2><p>Melden Sie sich mit Ihrem Dienstkonto an.</p><div class="field"><label for="uname">Benutzername</label><input id="uname" autocomplete="username" required placeholder="z. B. richter"></div><div class="field"><label for="pass">Passwort</label><input id="pass" type="password" autocomplete="current-password" required placeholder="••••••••"></div><div id="loginError" style="color:#a74b43;font-size:11px;min-height:17px"></div><button class="btn">Sicher anmelden&nbsp; →</button><div class="demo"><b>Demo-Zugänge</b><br>Schichtführer: <b>richter</b> / torb2026<br>Wachpersonal: <b>weber</b> / torb2026<br>Administration: <b>admin</b> / admin2026</div><div class="login-foot">Zugriff nur für autorisiertes Wachpersonal · Demo-System</div></form></section></div>';$('#loginForm').onsubmit=e=>{e.preventDefault();let found=db.users.find(x=>x.username===$('#uname').value.trim()&&x.password===$('#pass').value&&x.active);if(!found){$('#loginError').textContent='Anmeldung fehlgeschlagen. Zugangsdaten prüfen.';return}user={name:found.name,username:found.username,role:found.role};sessionStorage.setItem(SESSION,JSON.stringify(user));render()}}
function logout(){sessionStorage.removeItem(SESSION);user=null;startLogin()}
function render(){if(!user)return startLogin();let side=`<aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">TB</div><div><strong>DIENSTBUCH</strong><small>Elektronisches Wachbuch</small></div></div><div class="site-chip"><i class="dot"></i><div><b>WACHE TOR B</b><small>VW Motorenwerk · Chemnitz</small></div></div><div class="nav-label">Arbeitsbereich</div><nav class="nav">${navItems.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="ico">${ic}</span>${label}${id==='incidents'&&db.incidents.filter(x=>x.status!=='Abgeschlossen').length?`<span class="count">${db.incidents.filter(x=>x.status!=='Abgeschlossen').length}</span>`:''}</button>`).join('')}${admin()?`<div class="nav-label" style="margin-top:22px">Verwaltung</div><button data-page="users" class="${page==='users'?'active':''}"><span class="ico">⚙</span>Benutzerverwaltung</button>`:''}</nav><div class="side-bottom"><div class="shift-card"><small>AKTIVE SCHICHT</small><strong>Frühschicht · 06:00–14:00</strong><span>Begonnen um 06:00 Uhr</span><div class="progress"><i></i></div></div><div class="user-mini"><div class="avatar">${initials(user.name)}</div><div><b>${esc(user.name)}</b><small>${esc(user.role)}</small></div><button class="more" title="Abmelden" id="logout">⋯</button></div></div></aside>`;let title=navItems.find(x=>x[0]===page)?.[2]||(page==='users'?'Benutzerverwaltung':'Übersicht');document.getElementById('root').innerHTML=`<div class="app">${side}<main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn menu-toggle" id="menu">☰</button><div class="crumb">Wache TOR B&nbsp; / &nbsp;<b>${title}</b></div></div><div class="top-actions"><input class="search" id="globalSearch" placeholder="⌕  Suchen …" value="${esc(search)}"><button class="icon-btn" title="Aktuelle Zeit">◷</button><div class="avatar">${initials(user.name)}</div></div></header><section class="content" id="content">${page==='dashboard'?dashboard():page==='users'?usersPage():recordsPage(page)}</section></main></div>`;document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{page=x.dataset.page;render()});$('#logout').onclick=logout;$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#globalSearch').oninput=e=>{search=e.target.value;if(['incidents','visitors','keys','shifts','users'].includes(page))render()};wirePage()}
function dashboard(){let open=db.incidents.filter(x=>x.status!=='Abgeschlossen').length,onsite=db.visitors.filter(x=>x.status==='Anwesend').length,keys=db.keys.filter(x=>x.status==='Ausgegeben').length,now=new Date().toISOString().slice(0,10),today=db.incidents.filter(x=>x.time.slice(0,10)===now).length;let act=[...db.incidents.map(x=>({icon:'⚑',tone:x.priority==='Hoch'?'red':'',title:x.title,desc:`${x.place} · ${x.person}`,time:x.time})),...db.visitors.map(x=>({icon:'♙',tone:'green',title:`Besucher ${x.status==='Anwesend'?'angemeldet':'abgemeldet'}`,desc:`${x.name} · ${x.company}`,time:x.arrival}))].sort((a,b)=>new Date(b.time)-new Date(a.time)).slice(0,5);return `<div class="hello"><div><div class="eyebrow">Dienstag, 03. November 2026</div><h1>Guten Tag, ${esc(user.name.split(' ')[0])} 👋</h1><p>Hier ist die aktuelle Lageübersicht der Wache TOR B.</p></div><button class="btn" data-new="incident">＋&nbsp; Vorfall erfassen</button></div><div class="stats"><div class="stat"><div class="stat-top">Offene Vorfälle<span class="stat-icon">⚑</span></div><div class="stat-num">${open}</div><div class="stat-note"><em>${db.incidents.filter(x=>x.status==='In Bearbeitung').length} in Bearbeitung</em> · Aufmerksamkeit erforderlich</div></div><div class="stat"><div class="stat-top">Besucher im Objekt<span class="stat-icon">♙</span></div><div class="stat-num">${onsite.toString().padStart(2,'0')}</div><div class="stat-note">Aktuell angemeldete Gäste</div></div><div class="stat"><div class="stat-top">Ausgegebene Schlüssel<span class="stat-icon">⚿</span></div><div class="stat-num">${keys.toString().padStart(2,'0')}</div><div class="stat-note">Rückgabe zum Schichtende prüfen</div></div><div class="stat"><div class="stat-top">Vorfälle heute<span class="stat-icon">▤</span></div><div class="stat-num">${today||db.incidents.length}</div><div class="stat-note"><em>Schicht läuft</em> · seit 06:00 Uhr</div></div></div><div class="grid"><div class="panel"><div class="panel-head"><div><h2>Letzte Aktivitäten</h2><p>Aktuelle Einträge im Dienstbuch</p></div><button class="link" data-page="incidents">Alle Einträge →</button></div><div class="activity">${act.map(a=>`<div class="activity-item"><div class="activity-mark ${a.tone}">${a.icon}</div><div class="activity-copy"><b>${esc(a.title)}</b><p>${esc(a.desc)}</p></div><time class="activity-time">${date(a.time)}</time></div>`).join('')}</div></div><div class="right-col"><div class="panel handover"><div class="panel-head"><div><h2>Schichtstatus</h2><p>Aktuelle Besetzung</p></div><span class="badge green">Aktiv</span></div><div class="handover-body"><div class="handover-row"><span>Schichtführer</span><b>Jana Richter</b></div><div class="handover-row"><span>Schichtzeit</span><b>06:00 – 14:00</b></div><div class="handover-row"><span>Nächste Übergabe</span><b>in 4 Std. 12 Min.</b></div></div></div><div class="panel quick"><h2>Schnellzugriff</h2><div class="quick-list"><button data-new="visitor"><span>♙</span>Besucher anmelden</button><button data-new="key"><span>⚿</span>Schlüssel übergeben</button><button data-new="shift"><span>▤</span>Schichtprotokoll</button><button data-page="reports"><span>▧</span>Bericht erstellen</button></div></div></div></div>`}

