function recordsPage(p){let config={incidents:{name:'Vorfälle',sub:'Ereignisse und besondere Beobachtungen dokumentieren.',new:'Vorfall erfassen',type:'incident'},visitors:{name:'Besucherverwaltung',sub:'An- und Abmeldungen für Besucher und Fremdfirmen.',new:'Besucher anmelden',type:'visitor'},keys:{name:'Schlüsselübergaben',sub:'Nachvollziehbare Ausgabe und Rücknahme von Schlüsseln.',new:'Übergabe erfassen',type:'key'},shifts:{name:'Schichtprotokolle',sub:'Schichtverläufe, Übergaben und besondere Hinweise.',new:'Protokoll erstellen',type:'shift'},reports:{name:'Berichte & Export',sub:'Dienstbucheinträge prüfen und als PDF-Bericht ausgeben.',new:'Als PDF exportieren'}}[p];let data={incidents:db.incidents,visitors:db.visitors,keys:db.keys,shifts:db.shifts,reports:[...db.shifts,...db.incidents]}[p]||[];if(p==='reports')data=[...db.shifts,...db.incidents];let filtered=data.filter(x=>JSON.stringify(x).toLowerCase().includes(search.toLowerCase())&&(filter==='Alle'||x.status===filter));let filters=p==='incidents'?['Alle','Offen','In Bearbeitung','Abgeschlossen']:p==='visitors'?['Alle','Anwesend','Abgemeldet']:p==='keys'?['Alle','Ausgegeben','Zurückgegeben']:p==='shifts'?['Alle','Laufend','Abgeschlossen']:[];let headings={incidents:['Kennung / Vorfall','Ort','Meldende Person','Zeitpunkt','Priorität','Status'],visitors:['Besucher','Unternehmen / Anlass','Ansprechperson','Ankunft','Ausweis','Status'],keys:['Schlüssel / Nr.','Übergeben von → an','Zeitpunkt','Notiz','Status'],shifts:['Protokoll / Schicht','Schichtführer','Zeitraum','Zusammenfassung','Status'],reports:['Eintrag / Typ','Erfasst von','Zeitpunkt','Details','Status']}[p];let rows=filtered.map(x=>{if(p==='incidents')return `<tr><td><b>${esc(x.title)}</b><br><span style="color:#8a948d">${esc(x.id)} · ${esc(x.type)}</span></td><td>${esc(x.place)}</td><td>${esc(x.person)}</td><td>${date(x.time)}</td><td>${badge(x.priority)}</td><td>${badge(x.status)} ${canLead()&&x.status!=='Abgeschlossen'?`<button class="link" data-do